'use strict';

function mathLabel(id){return Mwrap(symbolMath(id));}
function numericBox(id,label,unit='',value=''){return `<label>${label}<div><input id="${id}" class="small" inputmode="decimal" value="${esc(value??'')}"> ${unit?Mwrap(unitMath(unit.replace(/²/g,'2').replace(/³/g,'3'))):''}<span id="${id}Status" role="status"></span></div></label>`;}
function choiceBlock(id,label,options,selected=''){const seed=[...id].reduce((s,c)=>s+c.charCodeAt(0),0)+(typeof heatKind==='number'?heatKind:0)+(typeof studyKey==='string'?studyKey.length:0),shift=seed%options.length,order=options.map((o,i)=>({o,i}));order.push(...order.splice(0,shift));return `<fieldset class="choice-group"><legend>${label}</legend>${order.map(({o,i},j)=>`<label><input type="radio" name="${id}" value="${i}" ${String(selected)===String(i)?'checked':''}> <b>${'abcd'[j]}.</b> ${taskText(o)}</label>`).join('')}</fieldset>`;}
function pickValue(id){return document.querySelector('[name='+id+']:checked')?.value??'';}
function selectList(id,options,value=''){return `<select id="${id}"><option value="">Valitse</option>${options.map((o,i)=>`<option value="${i}" ${String(value)===String(i)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
function planMarkup(prefix,c,st,scene){const choices=[...c.constants,c.variable,c.result];return `<h2>Suunnittele koe</h2><p><b>Tutkimuskysymys:</b> ${esc(c.title||c.question)}</p><div class="labgrid"><section>${planningArtwork(prefix,c)}</section><section><label>Nämä pidetään vakiona${selectList(prefix+'Fixed',[c.constants.join(', '),c.constants.slice(1).concat(c.variable).join(', '),c.constants.slice(0,2).concat(c.result).join(', ')],st.fixed)}</label><label>Tätä muutetaan${selectList(prefix+'Variable',[c.variable,c.constants[0],c.result],st.variable)}</label><label>Tätä mitataan${selectList(prefix+'Result',[c.variable,c.result,c.constants[0]],st.result)}</label><label>Hypoteesi<textarea id="${prefix}Hypothesis" placeholder="Mitä arvelet tapahtuvan? Perustele.">${esc(st.hypothesis||'')}</textarea></label><button id="${prefix}Plan">Tarkista ja aloita mittaukset →</button></section></div>`;}
function readPlan(prefix,st){st.fixed=el(prefix+'Fixed').value;st.variable=el(prefix+'Variable').value;st.result=el(prefix+'Result').value;st.hypothesis=el(prefix+'Hypothesis').value;return st;}
function validPlan(st){if(!st.hypothesis.trim()){message('Kirjoita hypoteesi ennen mittaamista.',false);return false;}if(st.fixed!=='0'||st.variable!=='0'||st.result!=='1'){message('Tarkista, mitä muutat, mitä mittaat ja mitkä tekijät pidät vakiona.',false);return false;}return true;}
function reliabilityMarkup(id,items){return `<fieldset class="choice-group"><legend>Mitkä tekijät voivat heikentää tuloksen luotettavuutta?</legend>${items.map((o,i)=>`<label><input type="checkbox" name="${id}" value="${i}"> ${esc(o)}</label>`).join('')}</fieldset>`;}
function checkedIndices(id){return [...document.querySelectorAll('[name='+id+']:checked')].map(n=>Number(n.value));}
function exactChoices(id,expected){const got=checkedIndices(id);return got.length===expected.length&&expected.every(i=>got.includes(i));}
const oldPlot=plot;
plot=function(points,options={}){const fit=options.fit,triangle=options.triangle;const xs=options.xstep||niceStep(options.xmax),ys=options.ystep||niceStep(options.ymax),xm=Math.ceil(options.xmax/xs)*xs,ym=Math.ceil(options.ymax/ys)*ys,X=x=>75+x/xm*515,Y=y=>270-y/ym*245;let s=oldPlot(points,{...options,xlabel:'',ylabel:'',fit:fit?.type==='linear'?null:fit});let extra='<defs><marker id="plotArrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6 Z" fill="#384744"/></marker></defs><path d="M75 270 H600 M75 270 V17" fill="none" stroke="#384744" stroke-width="1.7" marker-end="url(#plotArrow)"/>';
 function label(raw,x,y,anchor){let m=(raw||'').match(/^([^ (]+)\s*(.*)$/);if(!m)return '';return `<text x="${x}" y="${y}" text-anchor="${anchor}"><tspan font-style="italic">${esc(m[1].replace(/rho/g,'ρ'))}</tspan><tspan font-style="normal"> ${esc(m[2])}</tspan></text>`;}
 extra+=label(options.xlabel||'t (s)',590,323,'end')+label(options.ylabel||'s (m)',75,14,'start');if(fit?.type==='linear'){let end=fit.end??xm,b=fit.b||0;extra+=`<path d="M${X(0)} ${Y(b)} L${X(end)} ${Y(fit.k*end+b)}" fill="none" stroke="#195f58" stroke-width="2.5"/>`;}
 if(triangle){let [[x1,y1],[x2,y2]]=triangle;extra+=`<path d="M${X(x1)} ${Y(y1)} H${X(x2)} V${Y(y2)}" fill="none" stroke="#936337" stroke-width="2" stroke-dasharray="6 4"/><text x="${(X(x1)+X(x2))/2}" y="${Y(y1)>245?Y(y1)-12:Y(y1)+20}" text-anchor="middle" font-style="italic">${(options.xlabel||'t').startsWith('Δ')?'Δ'+options.xlabel.slice(1).split(' ')[0]:'Δ'+(options.xlabel||'t').split(' ')[0]}</text><text x="${X(x2)+10}" y="${(Y(y1)+Y(y2))/2}" font-style="italic">${(options.ylabel||'s').startsWith('Δ')?'Δ'+options.ylabel.slice(1).split(' ')[0]:'Δ'+(options.ylabel||'s').split(' ')[0]}</text>`;}return s.replace('</svg>',extra+'</svg>');};

const originalFormulaMath=formulaMath;
formulaMath=function(id){if(id==='Q')return renderEquationPreview('E=c*m*dT');if(id==='Ep')return renderEquationPreview('Ep=G*h');if(id==='expand')return renderEquationPreview('dl=alpha*l0*dT');return originalFormulaMath(id);};
