drawCalc=function(t){if(!calcIntroSeen){drawCalcIntroduction();return;}if(t.challenge){drawSandbox(t);return;}structuredCalc(t);};
function drawCalcIntroduction(){el('app').innerHTML=`<article class="panel"><h2>Näin kirjoitat ratkaisun</h2><p>2,0 kg vettä lämpenee 5,0 °C. Ominaislämpökapasiteetti on 4,2 kJ/(kg·°C). Laske veteen siirtyvä energia.</p><div class="columns"><section><h2>1. Lähtöarvot</h2>${renderGivenPreview('m=2 kg\nc=4.2 kJ/(kg*°C)\nΔT=5 °C')}</section><section><h2>2. Suureyhtälö</h2>${renderEquationPreview('E=c*m*dT')}</section><section><h2>3. Lasku ja tulos</h2>${renderWorkPreview('4.2 kJ/(kg*°C) * 2 kg * 5 °C = 42 kJ')}</section></div><p>Veteen siirtyy 42 kJ energiaa.</p><p>Perustehtävissä tarkistetaan ratkaisun vaiheet. Haastavissa tehtävissä saat vapaan työskentelytilan ja tarkistetaan lopputulos.</p><button id="beginCalculations">Aloita tehtävät</button></article>`;if(page==='8')el('app').innerHTML=el('app').innerHTML.replace(/<p>2,0 kg vettä[\s\S]*?<button id="beginCalculations">/,`<p>Pyöräilijä kulkee 240 m 30 sekunnissa. Laske keskinopeus.</p><div class="columns"><section><h2>1. Lähtöarvot</h2>${renderGivenPreview('s=240 m\nt=30 s')}</section><section><h2>2. Suureyhtälö</h2>${renderEquationPreview('v=s/t')}</section><section><h2>3. Lasku ja tulos</h2>${renderWorkPreview('(240 m)/(30 s)=8 m/s')}</section></div><p>Keskinopeus on 8 m/s.</p><p>Perustehtävissä tarkistetaan ratkaisun vaiheet. Haastavissa tehtävissä saat vapaan työskentelytilan ja tarkistetaan lopputulos.</p><button id="beginCalculations">`);el('beginCalculations').onclick=()=>{calcIntroSeen=true;drawTask();};}
function drawSandbox(t){const key='mafyke-f8-'+(['7','8'].includes(page)?'v19':'v10')+'-sandbox-'+page+'-'+index,st=saved(key,{work:'',answer:''});el('app').innerHTML=navigation()+bank()+`<article class="panel"><h2>${taskText(t.q)}</h2><p>Kirjoita laskut ja perustelut työskentelytilaan. Niitä ei tarkisteta: vain lopputulos tarkistetaan. Pyöristä vastaus kahteen tai kolmeen merkitsevään numeroon.</p><div class="symbol-buttons">${(page==='7'?['°C','Δt','Δl','α','l0','1/°C','kJ/(kg*°C)','≈','/()','·']:['ρ','Δ','²','sqrt()','≈','/()','·']).map(s=>`<button class="secondary" type="button" data-sandbox-insert="${s}">${s==='kJ/(kg*°C)'||s==='1/°C'?Mwrap(unitMath(s)):s==='l0'?Mwrap(symbolMath('l0')):esc(s==='/()'?'/':s)}</button>`).join('')}</div><p class="calc-toolbar-help">Kaava- ja merkkinapit nopeuttavat kirjoittamista. / lisää nimittäjän sulkeet.</p><label>Työskentelytila<textarea id="sandboxWork" rows="8">${esc(st.work)}</textarea></label><div id="sandboxPreview" class="math-preview"></div>${numericBox('sandboxAnswer','Lopputulos',t.unit,st.answer)}<button id="sandboxCheck">Tarkista vastaus</button><div id="feedback" class="feedback" role="status"></div><p id="score">Oikein ${Object.keys(done).length} / ${TASKS[page].length}</p></article>`;navEvents();const persist=()=>{st.work=el('sandboxWork').value;st.answer=el('sandboxAnswer').value;save(key,st);el('sandboxPreview').innerHTML=renderWorkspace(st.work);};el('sandboxWork').oninput=persist;el('sandboxAnswer').oninput=persist;document.querySelectorAll('[data-sandbox-insert]').forEach(b=>b.onclick=()=>{const n=el('sandboxWork');n.setRangeText(b.dataset.sandboxInsert,n.selectionStart,n.selectionEnd,'end');if(b.dataset.sandboxInsert==='/()')n.selectionStart=n.selectionEnd=n.selectionStart-1;n.focus();persist();});document.querySelectorAll('[data-formula]').forEach(b=>b.onclick=()=>{const n=el('sandboxWork'),s=(BASE_EQUATIONS[b.dataset.formula]||[])[0]||'';n.setRangeText(s,n.selectionStart,n.selectionEnd,'end');n.focus();persist();});el('sandboxCheck').onclick=()=>{persist();const good=calculationClose(number(st.answer),t.value);if(good)award();message(good?'✓ Vastaus oikein.':'Tarkista lopputulos ja annettu yksikkö.',good);};persist();}

HEAT_STUDIES[0].variable='Tutkittava neste';HEAT_STUDIES[0].constants=['Nesteen massa ja alkulämpötila','Lämmitysteho','Samanlaiset astiat ja mittaushetket'];
HEAT_STUDIES[1].end=120;HEAT_STUDIES[1].variable='Pinnan väri';HEAT_STUDIES[1].constants=['Levyjen materiaali, massa ja mitat','Alkulämpötila','Sama lamppu, etäisyys ja asento'];
HEAT_STUDIES[2].end=600;HEAT_STUDIES[2].labels=['Tumma','Kiiltävä'];HEAT_STUDIES[2].variable='Astian ulkopinnan materiaali';HEAT_STUDIES[2].constants=['Veden massa ja alkulämpötila','Astioiden muoto, koko ja kannet','Huonelämpötila ja mittaushetket'];
HEAT_STUDIES.forEach(c=>c.result='Lämpötila');Object.keys(heatCache).forEach(k=>delete heatCache[k]);
function loadHeat(){const st=saved('mafyke-f8-v7-heat-'+heatKind,{});heatStep=st.step||0;heatTime=st.time||0;heatRows=st.rows||[];heatNotes[heatKind]=st.notes||{};}
function persistHeat(){save('mafyke-f8-v7-heat-'+heatKind,{step:heatStep,time:heatTime,rows:heatRows,notes:heatNotes[heatKind]||{}});}
function heatTable(){return `<table><thead><tr><th>${mathLabel('t')} (s)</th>${heatLabels().map(x=>`<th>${esc(x)} (°C)</th>`).join('')}</tr></thead><tbody>${heatRows.map(r=>`<tr><td>${r[0].toFixed(1).replace('.',',')}</td>${r.slice(1).map(v=>`<td>${v.toFixed(1).replace('.',',')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function heatSchedule(){return Array.from({length:heatKind===2?6:5},(_,i)=>i*(heatKind===2?120:30));}
function heatComplete(){return heatTime>=HEAT_STUDIES[heatKind].end&&heatSchedule().every(t=>heatRows.some(r=>Math.abs(r[0]-t)<=(heatKind===2?25:9)));}
function drawHeat(){cancelAnimationFrame(heatRAF);heatRun=false;const c=HEAT_STUDIES[heatKind],notes=heatNotes[heatKind]||(heatNotes[heatKind]={}),plan=notes.plan||(notes.plan={});let body='';if(heatStep===0){body=planMarkup('heat',c,plan,heatScene());}else if(heatStep===1){body=`<h2>${esc(c.title)}</h2><p>${heatKind===2?'Kirjaa lämpötilamittaukset alussa ja sitten 2 minuutin välein 10 minuuttiin asti.':'Kirjaa lämpötilamittaukset alussa ja sitten 30 sekunnin välein 120 sekuntiin asti.'} Kello käy ${heatKind===2?'20':'8'} kertaa tavallista nopeammin.</p><div class="labgrid"><section><div id="heatScene">${heatScene()}</div><div id="heatClock" class="live">${heatClockText()}</div><div class="toolbar"><button id="heatStart" ${heatTime>=c.end?'disabled':''}>${heatTime>0?'Jatka mittausta':heatKind===2?'Käynnistä ajanotto':'Käynnistä lämmitys'}</button><button id="heatRecord" class="secondary">Kirjaa mittaus</button><button id="heatReset" class="secondary">Uusi mittaus</button></div></section><section><div id="heatTable">${heatTable()}</div><button id="heatResults" ${heatComplete()?'':'disabled'}>Kuvaaja ja päätelmät</button><p id="heatRemaining">${heatRemaining()}</p></section></div><button id="heatPlanning" class="secondary">Palaa suunnitteluun</button>`;}else{const curves=heatLabels().map((_,j)=>Array.from({length:101},(_,i)=>[c.end*i/100,heatTemp(c.end*i/100,j)]));body=`<h2>Tulokset ja päätelmät</h2><div class="labgrid"><section>${plot(heatRows.map(r=>[r[0],r[1]]),{xmax:c.end,ymax:heatKind===2?100:40,xstep:heatKind===2?120:30,ystep:10,xlabel:'t (s)',ylabel:'t (°C)',lines:false,series2:heatRows.map(r=>[r[0],r[2]]),curves})}<p>● ${heatLabels()[0]} · □ ${heatLabels()[1]}</p></section><section>${choiceBlock('heatObservation','Mitä havaitsit?',heatKind===0?['Vesi lämpeni nopeammin','Ruokaöljy lämpeni nopeammin']:heatKind===1?['Tumma levy lämpeni nopeammin','Vaalea levy lämpeni nopeammin']:['Tumma astia jäähtyi nopeammin','Kiiltävä astia jäähtyi nopeammin'],notes.observation)}${choiceBlock('heatExplanation','Mikä selittää tuloksen?',heatKind===0?['Vedellä on suurempi ominaislämpökapasiteetti','Öljyyn siirtyi enemmän energiaa','Veden suurempi tiheys yksin määrää lämpötilan nousun','Öljyn ominaislämpökapasiteetti on suurempi']:heatKind===1?['Tumma pinta imee lampun säteilyä tehokkaammin','Tumma pinta johtaa energiaa takaisin lamppuun tehokkaammin','Vaalea pinta imee lampun säteilyä tehokkaammin','Levyjen sama massa aiheuttaa eri lämpötilan nousun pintojen väristä riippumatta']:['Tumma pinta lähettää lämpösäteilyä tehokkaammin','Kiiltävä pinta luovuttaa lämpösäteilyä tehokkaammin','Tumman astian lämpötilan lasku todistaa veden ominaislämpökapasiteetin muuttuneen','Samanlainen lämmön johtuminen selittää yksin astioiden välisen eron'],notes.explanation)}${reliabilityMarkup('heatReliability',['Lämpömittarit näyttävät samassa vedessä eri lukemaa','Näytteet ovat aluksi eri lämpötiloissa',heatKind===2?'Toisen astian kansi on raollaan':'Toinen lämmitin on tehokkaampi tai toinen levy on lähempänä lamppua','Lämpötilat kirjataan eri ajanhetkillä','Samanlaiset astiat kaikissa mittauksissa','Anturit pidetään samalla syvyydellä'])}<button id="heatConclusions">Tarkista päätelmät</button></section></div><button id="heatBack" class="secondary">Palaa mittaukseen</button><button id="heatPlanning" class="secondary">Palaa suunnitteluun</button>`;}
 el('app').innerHTML=`<div class="toolbar"><label>Tutkimus<select id="heatKind">${HEAT_STUDIES.map((c,i)=>`<option value="${i}" ${i===heatKind?'selected':''}>${i+1}. ${esc(c.title)}</option>`).join('')}</select></label></div>${steps(heatStep)}<article class="panel">${body}<div id="feedback" class="feedback" role="status"></div></article>`;el('heatKind').onchange=e=>{if(heatStep===0)readPlan('heat',plan);persistHeat();heatKind=Number(e.target.value);loadHeat();drawHeat();};if(heatStep===0)el('heatPlan').onclick=()=>{readPlan('heat',plan);persistHeat();if(!validPlan(plan))return;heatStep=1;persistHeat();drawHeat();};
 if(heatStep>0)el('heatPlanning').onclick=()=>{heatStep=0;persistHeat();drawHeat();};if(heatStep===1){el('heatStart').onclick=()=>{if(heatRun||heatTime>=c.end)return;if(!heatRows.some(r=>r[0]===0)){message('Kirjaa alkulämpötilat ennen ajan käynnistämistä.',false);return;}heatRun=true;heatLast=performance.now();el('heatScene').innerHTML=heatScene();el('heatStart').disabled=true;heatRAF=requestAnimationFrame(heatTick);};el('heatRecord').onclick=()=>{const interval=heatKind===2?120:30,slot=Math.round(heatTime/interval),target=slot*interval,tol=heatKind===2?25:9;if(Math.abs(heatTime-target)>tol){message('Kirjaa mittaus lähellä '+target+' sekunnin ajankohtaa.',false);return;}if(heatRows.some(r=>Math.round(r[0]/interval)===slot)){message('Tämä mittaushetki on jo kirjattu.',false);return;}heatRows.push([heatTime,...heatLabels().map((_,j)=>Number(heatTemp(heatTime,j).toFixed(1)))]);persistHeat();el('heatTable').innerHTML=heatTable();el('heatRemaining').textContent=heatRemaining();el('heatResults').disabled=!heatComplete();message('Mittaus kirjattu.',true);};el('heatReset').onclick=()=>{heatTime=0;heatRows=[];persistHeat();drawHeat();};el('heatResults').onclick=()=>{if(!heatComplete()){message('Mittaa kaikki ohjeen ajankohdat ja odota kokeen loppuun.',false);return;}heatStep=2;persistHeat();drawHeat();};}
 if(heatStep===2){el('heatConclusions').onclick=()=>{notes.observation=pickValue('heatObservation');notes.explanation=pickValue('heatExplanation');notes.reliability=pickValue('heatReliability');persistHeat();const good=notes.observation===String(heatKind===0?1:0)&&notes.explanation==='0'&&pickValue('heatReliability')==='0';message(good?'✓ Havainto, selitys ja luotettavuustekijät oikein.':'Tarkista havainto kuvaajasta ja mieti, mitkä tekijät muuttavat lukemia.',good);};el('heatBack').onclick=()=>{heatStep=1;persistHeat();drawHeat();};}
}
function heatRemaining(){const missing=heatSchedule().filter(t=>!heatRows.some(r=>Math.abs(r[0]-t)<=(heatKind===2?25:9)));return missing.length?'Vielä kirjattavat ajankohdat: '+missing.map(t=>t+' s').join(', '):heatTime<HEAT_STUDIES[heatKind].end?'Odota kokeen päättymistä.':'Kaikki mittaushetket kirjattu.';}
function heatClockText(){return 't = '+heatTime.toFixed(1).replace('.',',')+' s / '+HEAT_STUDIES[heatKind].end+' s';}
function heatTick(now){if(!heatRun)return;heatTime=Math.min(HEAT_STUDIES[heatKind].end,heatTime+(now-heatLast)/1000*(heatKind===2?20:8));heatLast=now;el('heatClock').textContent=heatClockText();updateHeatScene();if(heatTime>=HEAT_STUDIES[heatKind].end){heatRun=false;persistHeat();updateHeatScene();el('heatResults').disabled=!heatComplete();message('Koe päättyi. Kirjaa viimeinen mittaus.',true);}else heatRAF=requestAnimationFrame(heatTick);}
