function expObserved(k,i,repeat){const r={...idealExpReading(k,i)},seed=[...k].reduce((a,c)=>a*31+c.charCodeAt(0),17)+i*271+repeat*911,unit=((Math.sin(seed*12.9898)*43758.5453)%1+1)%1-.5;r.key=k;r.level=i;if(k==='load'||k==='material')r.force=Number((r.force*(1+unit*(k==='material'?.08:.035))).toFixed(2));else if(k==='buoyancy')r.wet=Number((r.wet+unit*.04).toFixed(2));else r.time=Number((r.time+unit*.04).toFixed(2));return r;}
const idealExpReading=typeof expReading==='function'?expReading:null;
if(idealExpReading)expReading=function(k,i){return expMeasured?.key===k&&expMeasured.level===i&&(expRunning||expState().ready||expState().lastReading?.level===i)?expMeasured:idealExpReading(k,i);};
const basicExpUpdate=typeof updateExperimentScene==='function'?updateExperimentScene:null;
updateExperimentScene=function(){basicExpUpdate();if(expMeasured&&el('expMeter')){if(studyKey==='buoyancy'){let {v}=buoyGeometry(),target=expMeasured.x,fraction=target?v/target:0,F=12-v*.01+(expMeasured.wet-(12-target*.01))*fraction;el('expMeter').textContent=F.toFixed(2).replace('.',',')+' N';}else if(isPower())el('expMeter').textContent=(expMeasured.time*expProgress).toFixed(2).replace('.',',')+' s';}};
function drawExperiment(){stopExp();const c=STUDIES[studyKey],s=expState();s.step=Math.min(s.step,2);if(s.ready&&s.pending)expMeasured={...s.pending};else if(s.lastReading?.level===s.level)expMeasured={...s.lastReading};s.plan=s.plan||{};let body='';if(s.step===0)body=planMarkup('exp',{...c,title:c.question},s.plan,expScene());else if(s.step===1)body=`<h2>${esc(c.title)}</h2><p>Mittaa jokaisella asetuksella kerran. Voit uusia mittauksen tarvittaessa.</p><div class="labgrid"><section><label>${esc(c.variable)}<select id="expLevel">${c.levels.map((_,i)=>`<option value="${i}" ${i===s.level?'selected':''}>${esc(expLevelName(i))}</option>`).join('')}</select></label><div id="expScene">${expScene()}</div><div class="toolbar">${studyKey==='buoyancy'?'<button id="expAir" class="secondary">Mittaa ilmassa</button>':''}<button id="expRun">${studyKey==='buoyancy'?'Upota ja mittaa':isPower()?'Käynnistä nosto':'Käynnistä tasainen veto'}</button><button id="expRecord" ${s.ready?'':'disabled'}>Kirjaa lukema</button></div><p id="expLive">${s.ready?'Mittaus valmis. Kirjaa lukema.':'Valitse asetus ja käynnistä mittaus.'}</p></section><section><div id="expMeasurements">${expTable()}</div><button id="expResults">Tulokset ja laskut</button></section></div>`;else{const obs=studyKey==='load'?['Liikekitka kasvaa kokonaismassan mukana','Liikekitka säilyy, koska kosketuspinta-ala säilyy','Liikekitka pienenee kuorman kasvaessa','Liikekitka riippuu vain vetomatkasta']:studyKey==='material'?['Liikekitka riippuu materiaaliparista','Kaikkien pintojen kitka on sama','Kitka riippuu vain liikkeen suunnasta','Kitka on sitä suurempi, mitä kevyempi palikka on']:studyKey==='buoyancy'?['Noste kasvaa upotetun tilavuuden mukana','Noste kasvaa vain upotussyvyyden, ei tilavuuden mukana','Noste on sama kuin jousivaa’an lukema vedessä','Noste riippuu vain kappaleen massasta']:studyKey==='height'?['Nostoteho pysyy likimäärin samana','Nostoteho kasvaa korkeuden mukana','Nostoteho pienenee korkeuden mukana','Teho on sama suure kuin työ']:['Nostoteho kasvaa tutkitun muuttujan kasvaessa','Nostoteho pienenee tutkitun muuttujan kasvaessa','Nostoteho pysyy vakiona','Nostoteho riippuu vain korkeudesta'];const explanation=studyKey==='buoyancy'?['Noste on syrjäytetyn nesteen painon suuruinen','Noste on kappaleen painon suuruinen kaikissa tilanteissa','Noste on syrjäytetyn nesteen massan suuruinen','Noste on aina painovoimaa suurempi']:studyKey==='load'?['Tukivoima kasvaa kuorman kasvaessa','Kosketuspinta-ala kasvaa massan mukana','Vetomatka kasvaa kuorman mukana','Palikan nopeus määrää yksin kitkan']:studyKey==='material'?['Pintojen vuorovaikutus ja kunto vaikuttavat kitkaan','Kaikilla materiaaleilla on sama kitkakerroin','Materiaali vaikuttaa vain lepokitkaan','Suurempi vetomatka pienentää kitkaa']:studyKey==='height'?['Työ ja aika kasvavat samassa suhteessa','Työ säilyy ja aika kasvaa','Aika säilyy ja työ kasvaa','Työ kasvaa mutta aika lyhenee']:studyKey==='speed'?['Sama työ tehdään lyhyemmässä ajassa','Työ kasvaa nopeuden neliössä','Kuorman paino pienenee','Hyötysuhde määrää yksin nostotehon']:['Nostovoima kasvaa kuorman mukana','Nostoaika lyhenee kuorman mukana','Nostokorkeus kasvaa kuorman mukana','Työ säilyy massan muuttuessa'];const conclusions=`<h2>Päätelmät</h2><div class="labgrid"><section>${expGraphs()}<details class="measurement-calculations"><summary>Mittaukset ja laskut</summary>${expTable()}<p>${studyKey==='buoyancy'?renderEquationPreview('Fn=G-F'):isPower()?renderEquationPreview('W=F*h')+renderEquationPreview('P=W/t'):renderEquationPreview('Fmu=F')}</p><div class="resultnums">${expAnswerSpecs().map(([label,unit],i)=>numericBox('expAnswer'+i,label,unit,s.answers[i]||'')).join('')}</div><p>${studyKey==='buoyancy'?'Noste on ilmassa ja vedessä saatujen lukemien erotus. Käytä tiheyden laskussa yksikköä m³.':isPower()?'Laske työ voiman ja korkeuden tulona. Jaa työ mitatulla ajalla.':'Kitkakerroin on kitkavoima jaettuna kokonaispainolla.'} g = 10 N/kg.</p><button id="expCheck">Tarkista laskut</button></details></section><section>${choiceBlock('expObservation','Mitä havaitsit?',obs)}${choiceBlock('expExplanation','Mikä selittää havainnon?',explanation)}${reliabilityMarkup('expReliability',['Mittari ei näytä nollaa ennen mittausta','Lukema luetaan väärin tai kello käynnistetään myöhässä',studyKey==='buoyancy'?'Kappaleen kosketus astian pohjaan':isPower()?'Nostonopeuden vaihtelu':'Palikkaa vedetään vinoon ylöspäin','Sama kappale tai kuorma pidetään paikallaan punnituksen aikana','Samaa mittaria käytetään koko mittaussarjassa'])}<button id="expSave">Tarkista päätelmät</button></section></div>`;body=conclusions;}
 el('app').innerHTML=courseTabs()+`<div class="toolbar"><label>Tutkimus<select id="expStudy">${expAllowed.map(k=>`<option value="${k}" ${k===studyKey?'selected':''}>${esc(STUDIES[k].title)}</option>`).join('')}</select></label><button id="expReset" class="secondary">Aloita alusta</button></div>${steps(s.step)}<article class="panel">${body}${s.step>0?'<div class="toolbar"><button id="expPlanning" class="secondary">Palaa suunnitteluun</button><button id="expBack" class="secondary">Palaa mittauksiin</button></div>':''}<div id="feedback" class="feedback" role="status"></div></article>`;courseNavEvents();el('expStudy').onchange=e=>{if(s.step===0)readPlan('exp',s.plan);persistExp();studyKey=e.target.value;expMeasured=null;expProgress=0;drawExperiment();};el('expReset').onclick=()=>{delete expStates[studyKey];expMeasured=null;expProgress=0;persistExp();drawExperiment();};if(s.step>0){el('expPlanning').onclick=()=>{s.step=0;persistExp();drawExperiment();};el('expBack').onclick=()=>{s.step=1;persistExp();drawExperiment();};}
 if(s.step===0)el('expPlan').onclick=()=>{readPlan('exp',s.plan);s.notes.prediction=s.plan.hypothesis;persistExp();if(!validPlan(s.plan))return;s.step=1;persistExp();drawExperiment();};
 if(s.step===1){el('expLevel').onchange=e=>{s.level=Number(e.target.value);s.pose='air';s.ready=false;expMeasured=null;expProgress=0;persistExp();drawExperiment();};if(studyKey==='buoyancy')el('expAir').onclick=()=>{s.airMeasured=true;s.pose='air';s.ready=false;expProgress=0;persistExp();el('expScene').innerHTML=expScene();message('Ilmassa 12,00 N. Mittaa seuraavaksi vedessä.',true);};el('expRun').onclick=()=>{if(expRunning)return;if(studyKey==='buoyancy'&&!s.airMeasured){message('Mittaa ensin ilmassa.',false);return;}s.ready=false;expProgress=0;expMeasured=expObserved(studyKey,s.level,s.rows.filter(r=>r.level===s.level).length);s.pending={...expMeasured};expDuration=isPower()?expMeasured.time:2.2;expRunning=true;expLast=performance.now();el('expRecord').disabled=!['load','material'].includes(studyKey);el('expLevel').disabled=true;el('expRun').disabled=true;if(el('expAir'))el('expAir').disabled=true;el('expLive').textContent='Mittaus käynnissä…';expRAF=requestAnimationFrame(expTick);};el('expRecord').onclick=()=>{if((!s.ready||expRunning)&&!(expRunning&&['load','material'].includes(studyKey)))return;if(s.rows.filter(r=>r.level===s.level).length>=expRepeats()){message('Poista aiempi mittaus, jos haluat uusia sen.',false);return;}const measured=s.pending||expMeasured;if(!measured||measured.level!==s.level){message('Tee mittaus uudelleen.',false);return;}s.notes.calculations=false;s.rows.push({...measured});s.lastReading={...measured};s.ready=false;if(!expRunning)s.pending=null;persistExp();if(expRunning){el('expMeasurements').innerHTML=expTable();document.querySelectorAll('[data-delete-reading]').forEach(b=>b.onclick=()=>{s.notes.calculations=false;s.rows.splice(Number(b.dataset.deleteReading),1);persistExp();drawExperiment();});el('expRecord').disabled=true;message('✓ Lukema kirjattu. Veto jatkuu.',true);}else drawExperiment();};document.querySelectorAll('[data-delete-reading]').forEach(b=>b.onclick=()=>{s.notes.calculations=false;s.rows.splice(Number(b.dataset.deleteReading),1);persistExp();drawExperiment();});el('expResults').onclick=()=>{if(expGroups().some(g=>g.n<expRepeats())){message('Mittaa kaikki asetukset ennen tuloksia.',false);return;}s.step=2;persistExp();drawExperiment();};}
 if(s.step>=2)el('expCheck').onclick=()=>{const specs=expAnswerSpecs();specs.forEach((_,i)=>s.answers[i]=el('expAnswer'+i).value);persistExp();if(specs.some((a,i)=>!near(number(s.answers[i]),a[2],.09))){message('Tarkista laskut omista mittaustuloksista.',false);return;}s.notes.calculations=true;persistExp();message('✓ Laskut oikein.',true);};if(s.step>=2)el('expSave').onclick=()=>{const good=pickValue('expObservation')==='0'&&pickValue('expExplanation')==='0'&&pickValue('expReliability')==='0';s.notes.conclusions={observation:pickValue('expObservation'),explanation:pickValue('expExplanation'),reliability:pickValue('expReliability')};persistExp();message(good?'✓ Päätelmät oikein.':'Tarkista havainnot, selitys ja luotettavuuteen vaikuttavat tekijät.',good);};
}
function expansionScene(){const T=expansionState.temperature;let s=sceneOpen(420,'Lämpölaajenemisen mittaus')+inkBench(365)+`<path d="M35 130 L53 112 H353 L374 130 V350 H35 Z" fill="#c0d4d4" stroke="#435953" stroke-width="2"/><rect x="48" y="138" width="313" height="202" rx="4" fill="#d7e9e7" stroke="#809b97"/><path d="M66 141 V336" stroke="url(#steel)" stroke-width="9"/>`+inkMeter(104,12,T.toFixed(1).replace('.',',')+' °C','Lämpöhaude','expansionTemperature');['Kupari','Rauta'].forEach((name,j)=>{let y=182+j*115,d=expansionDelta(T,j),end=340+d*.274;s+=`<path id="expansionRod${j}" d="M70 ${y} H${end}" stroke="${j?'url(#steel)':'url(#brass)'}" stroke-width="13"/><rect x="63" y="${y-12}" width="15" height="24" rx="2" fill="#687f78" stroke="#435953"/><circle cx="70" cy="${y}" r="3" fill="#d9e0d3"/><text x="195" y="${y-24}" text-anchor="middle">${name} · 1,00 m</text><path d="M${end} ${y} H451" stroke="url(#steel)" stroke-width="4"/><circle cx="500" cy="${y}" r="49" fill="#526b64" stroke="#2b4038" stroke-width="2"/><circle cx="500" cy="${y}" r="43" fill="#fffdf3" stroke="#a9b6a2"/>`;for(let i=0;i<=30;i++){let a=(130+i*280/30)*Math.PI/180,r1=i%10===0?31:36,r2=40,x1=500+r1*Math.cos(a),y1=y+r1*Math.sin(a),x2=500+r2*Math.cos(a),y2=y+r2*Math.sin(a);s+=`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="#435953" stroke-width="${i%10?'.7':'1.3'}"/>`;if(i%10===0)s+=`<text x="${500+24*Math.cos(a)}" y="${y+24*Math.sin(a)+3}" text-anchor="middle" style="font-size:9px">${fmt(i*.05)}</text>`;}s+=`<g id="expansionNeedle${j}" transform="rotate(${130+d/1.5*280} 500 ${y})"><path d="M500 ${y} H538" stroke="#195f58" stroke-width="2"/></g><circle cx="500" cy="${y}" r="3" fill="#435953"/><text id="expansionValue${j}" x="500" y="${y+67}" text-anchor="middle" style="font-size:15px">${d.toFixed(2).replace('.',',')} mm</text>`;});s+='<text x="500" y="105" text-anchor="middle" style="font-size:14px">Pitenemismittarit</text><circle id="expansionPower" cx="340" cy="350" r="4" fill="'+(expansionRunning?'#e9aa3e':'#647366')+'"/></svg>';return s;}
function updateExpansionScene(){let T=expansionState.temperature;el('expansionTemperature').textContent=T.toFixed(1).replace('.',',')+' °C';[0,1].forEach(j=>{let d=expansionDelta(T,j);setSvgAttr('expansionRod'+j,'d',`M70 ${182+j*115} H${340+d*.274}`);setSvgAttr('expansionNeedle'+j,'transform',`rotate(${130+d/1.5*280} 500 ${182+j*115})`);el('expansionValue'+j).textContent=d.toFixed(2).replace('.',',')+' mm';});setSvgAttr('expansionPower','fill',expansionRunning?'#e9aa3e':'#647366');}
const expansionConfig={title:'Miten lämpötila vaikuttaa metallisauvan pituuteen?',variable:'Sauvojen lämpötila',result:'Sauvojen piteneminen',constants:['Sama alkupituus ja alkulämpötila','Samat sauvat ja kiinnitys','Molemmat sauvat samassa lämpöhauteessa']};
function drawExpansion(){expansionStop();const st=expansionState;st.step=st.step||0;st.plan=st.plan||{};let body='';if(st.step===0)body=planMarkup('expansion',expansionConfig,st.plan,expansionScene());else if(st.step===1)body=`<h2>Lämpölaajenemisen mittaus</h2><p>Mittaa alussa 20 °C:ssa ja sitten lämpötiloissa 40, 60, 80 ja 100 °C. Molempien sauvojen alkupituus on 1,00 m.</p><div class="labgrid"><section><div id="expansionScene">${expansionScene()}</div><label>Tavoitelämpötila<select id="expansionTarget">${[20,40,60,80,100].map(T=>`<option value="${T}">${T} °C</option>`).join('')}</select></label><div class="toolbar"><button id="expansionHeat">${st.temperature>20?'Jatka lämmitystä':'Käynnistä lämmitys'}</button><button id="expansionRecord">Kirjaa mittaus</button></div></section><section>${expansionTable()}<button id="expansionResults">Kuvaaja ja päätelmät</button></section></div>`;else{body=`<h2>Kuvaaja ja pituuden lämpötilakerroin</h2><div class="labgrid"><section>${plot(st.rows.map(r=>[r[0]-20,r[1]]),{series2:st.rows.map(r=>[r[0]-20,r[2]]),xmax:80,ymax:1.5,xstep:20,ystep:.25,xlabel:'ΔT (°C)',ylabel:'Δl (mm)',lines:false,curves:[[[0,0],[80,1.36]],[[0,0],[80,.96]]],triangle:[[20,.34],[80,1.36]]})}<p>● Kupari · □ Rauta</p>${expansionTable()}</section><section><p>${renderEquationPreview('dl=alpha*l0*dT')}${renderEquationPreview('alpha=dl/(l0*dT)')}</p>${numericBox('expansionDT','Kuparin apukolmion lämpötilan muutos','°C')}${numericBox('expansionDL','Kuparin apukolmion piteneminen','mm')}${numericBox('expansionMetres','Sama piteneminen metreinä','m')}${numericBox('expansionAlpha','Kuparin pituuden lämpötilakerroin','1/°C')}${numericBox('ironAlpha','Raudan pituuden lämpötilakerroin','1/°C')}${choiceBlock('expansionCompare','Lämpötilan muutos kaksinkertaistuu. Mitä tapahtuu pitenemiselle?',['Se kaksinkertaistuu','Se puolittuu','Se pysyy samana','Se nelinkertaistuu'])}<button id="expansionCheck">Tarkista</button></section></div>`;}
 el('app').innerHTML=courseTabs()+steps(st.step)+`<article class="panel">${body}${st.step?'<button id="expansionPlanning" class="secondary">Palaa suunnitteluun</button>':''}<button id="expansionReset" class="secondary">Aloita alusta</button><div id="feedback" class="feedback" role="status"></div></article>`;courseNavEvents();el('expansionReset').onclick=()=>{expansionState={temperature:20,rows:[],notes:{},step:0,plan:{}};expansionSave();drawExpansion();};if(st.step)el('expansionPlanning').onclick=()=>{st.step=0;expansionSave();drawExpansion();};if(st.step===0)el('expansionPlan').onclick=()=>{readPlan('expansion',st.plan);expansionSave();if(!validPlan(st.plan))return;st.step=1;expansionSave();drawExpansion();};if(st.step===1){el('expansionTarget').value=[20,40,60,80,100].find(t=>!st.rows.some(r=>r[0]===t))??100;el('expansionHeat').onclick=()=>{if(expansionRunning)return;if(!st.rows.some(r=>r[0]===20)){message('Kirjaa alkumittaus 20 °C:ssa.',false);return;}expansionRunning=true;expansionLast=performance.now();el('expansionTarget').disabled=true;el('expansionHeat').disabled=true;expansionRAF=requestAnimationFrame(expansionTick);};el('expansionRecord').onclick=()=>{let target=Number(el('expansionTarget').value);if(expansionRunning||Math.abs(st.temperature-target)>.01){message('Odota tavoitelämpötilaa.',false);return;}if(st.rows.some(r=>r[0]===target)){message('Tämä lämpötila on jo kirjattu.',false);return;}st.rows.push([target,...[0,1].map(j=>Number(expansionDelta(target,j).toFixed(2)))]);st.rows.sort((a,b)=>a[0]-b[0]);expansionSave();drawExpansion();};el('expansionResults').onclick=()=>{if(st.rows.length<5){message('Kirjaa alkuarvot ja kaikki neljä lämmitysmittausta.',false);return;}st.step=2;expansionSave();drawExpansion();};}if(st.step===2)el('expansionCheck').onclick=()=>{const specs=[['expansionDT',60],['expansionDL',1.02],['expansionMetres',.00102],['expansionAlpha',.000017],['ironAlpha',.000012]];let good=specs.every(([id,v])=>near(number(el(id).value),v,.12))&&pickValue('expansionCompare')==='0';message(good?'✓ Pituuden lämpötilakertoimet ja päätelmä oikein.':'Lue apukolmion erot suoralta. Muunna millimetrit metreiksi ennen kertoimen laskua.',good);};}
function expansionTable(){return `<table><thead><tr><th>T (°C)</th><th>Kupari Δl (mm)</th><th>Rauta Δl (mm)</th></tr></thead><tbody>${expansionState.rows.map(r=>`<tr>${r.map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function expansionTick(now){if(!expansionRunning)return;const target=Number(el('expansionTarget').value),T=expansionState.temperature,step=(now-expansionLast)/1000*12;expansionLast=now;expansionState.temperature=T+Math.sign(target-T)*Math.min(step,Math.abs(target-T));updateExpansionScene();if(Math.abs(expansionState.temperature-target)<.001){expansionState.temperature=target;expansionStop();expansionSave();updateExpansionScene();el('expansionTarget').disabled=false;el('expansionHeat').disabled=false;el('expansionHeat').textContent='Jatka lämmitystä';message('Tavoitelämpötila saavutettu. Kirjaa mittaus.',true);}else expansionRAF=requestAnimationFrame(expansionTick);}
let motionMenu=true;
function length(){return motionKind===2?40:4;}
function pos(){return motionKind===0?.8*motionT:.5*accel()*motionT**2;}
function endTime(){return motionKind===0?5:Math.sqrt(2*length()/accel());}
function motionEst(){const first=captured[0],last=captured.at(-1),before=captured.at(-2),t0=first[0]/2,t1=(before[0]+last[0])/2,v0=first[1]/first[0],v1=(last[1]-before[1])/(last[0]-before[0]);return {t0,t1,v0,v1,a:(v1-v0)/(t1-t0),dt0:first[0],ds0:first[1],dt1:last[0]-before[0],ds1:last[1]-before[1]};}
function motionDataTable(){return `<table class="motion-table"><caption>Omat mittaustulokset</caption><thead><tr><th>${mathLabel('s')} (m)</th><th>${mathLabel('t')} (s)</th></tr></thead><tbody><tr><td>0</td><td>0</td></tr>${captured.map(([t,s])=>`<tr><td>${fmt(s)}</td><td>${t.toFixed(2).replace('.',',')}</td></tr>`).join('')}</tbody></table>`;}
let motionStudentAcceleration=null;
function guidedRatio(id,label,unit,aLabel,bLabel){const top=unit==='m/s'?'m':'m/s',formula=unit==='m/s'?'v=Δs/Δt':'a=Δv/Δt';return `<section class="ratio-task" data-ratio="${id}" data-unit="${unit}"><h3>${label}</h3><p>${renderEquationPreview(formula)}</p><div class="guided-equation">${numericBox(id+'Numerator',aLabel,top)}${numericBox(id+'Denominator',bLabel,'s')}</div><div id="${id}Fraction" class="ratio-preview">${ratioPreview(id,unit,'','')}</div>${numericBox(id+'Value','Tulos kahden merkitsevän numeron tarkkuudella',unit)}</section>`;}
function ratioPreview(id,unit,a,b){const quantity=(v,u)=>Mtag('mrow',v.trim()?Mtag('mn',esc(v)):Mtag('mtext','…'),'<mspace width="0.2em"/>',unitMath(u));const x=number(a),y=number(b),value=Number.isFinite(x)&&Number.isFinite(y)&&y!==0?x/y:null;return Mwrap(Mtag('mrow',symbolMath(unit==='m/s'?'v':'a'),Mtag('mo','='),Mtag('mfrac',quantity(a,unit==='m/s'?'m':'m/s'),quantity(b,'s')),value===null?'':Mtag('mrow',Mtag('mo','='),quantity(String(Number(value.toPrecision(5))).replace('.',','),unit),Mtag('mo','≈'),quantity(value.toPrecision(2).replace('.',','),unit))));}
function bindRatioPreviews(){document.querySelectorAll('[data-ratio]').forEach(box=>{const id=box.dataset.ratio,unit=box.dataset.unit,refresh=()=>{el(id+'Fraction').innerHTML=ratioPreview(id,unit,el(id+'Numerator').value,el(id+'Denominator').value);};el(id+'Numerator').oninput=refresh;el(id+'Denominator').oninput=refresh;refresh();});}

function drawMotion(){motionStep=Math.min(motionStep,2);cancelAnimationFrame(motionRAF);motionRun=false;if(motionMenu){el('app').innerHTML=`<div class="grid motion-menu">${['Leikkiauton liike','Kuulan vieriminen','Kuulan pudotus tornista'].map((name,i)=>`<article class="panel"><h2>${name}</h2><p>${['Tutki neljän metrin matkaa pitkällä pöydällä.','Tutki levosta lähtevää kuulaa kaltevalla radalla.','Kirjaa väliajat 40 metrin pudotuksessa.'][i]}</p><button data-motion-open="${i}">Avaa tutkimus</button></article>`).join('')}</div>`;document.querySelectorAll('[data-motion-open]').forEach(b=>b.onclick=()=>{motionKind=Number(b.dataset.motionOpen);angle=12;motionStep=0;motionT=0;captured=[];motionMenu=false;drawMotion();});return;}let body='';if(motionStep===0)body=`<h2>${['Leikkiauton liike','Kuulan vieriminen','Pudotus tornista'][motionKind]}</h2>${ruler()}<p>${['Kirjaa väliajat metrin välein auton keskikohdan ohittaessa merkin.','Kuula lähtee levosta ja vierii kaltevalla radalla. Kirjaa väliajat 0,5 metrin välein.','Kuula pudotetaan levosta tornin tasanteelta. Kirjaa väliajat 5 metrin välein.'][motionKind]}</p><p>${motionKind===0?'Kello käy tavallista nopeutta.':'Liike ja ajanotto on hidastettu puoleen. Kello näyttää kokeen ajan.'}</p><button id="startMotion">Siirry mittaukseen</button>`;else if(motionStep===1)body=`<div class="labgrid"><section><div id="motionScene">${ruler()}</div><div id="motionClock" class="live">t = ${motionT.toFixed(2).replace('.',',')} s</div><div class="toolbar"><button id="runMotion">${motionT>0?'Jatka mittausta':'Käynnistä mittaus'}</button><button id="capture">Väliaika: ${fmt(marks[captured.length]??length())} m</button><button id="retryMotion" class="secondary">Uusi mittaus</button></div><p>Kirjaa väliaika painikkeella tai välilyönnillä.</p></section><section><div id="motionTable">${motionDataTable()}</div><button id="motionResults">Kuvaaja ja laskut</button></section></div>`;else if(motionStep===2){const fit=motionFit(),e=motionEst(),x1=0,x2=motionTriangleTime(),triangle=motionKind===0?[[x1,fit.k*x1],[x2,fit.k*x2]]:null;body=`<h2>Matka ajan funktiona</h2><div class="labgrid"><section>${plot([[0,0],...captured],{xmax:captured.at(-1)[0]*1.15,ymax:length()*1.12,xlabel:'t (s)',ylabel:'s (m)',lines:false,fit,triangle})}${motionDataTable()}</section><section>${motionKind===0?guidedRatio('speed','Nopeus apukolmiosta','m/s','Apukolmion matkan muutos','Apukolmion ajan muutos'):`<p>Laske ensimmäisen ja viimeisen mittausvälin keskinopeudet. Käytä taulukon vierekkäisiä rivejä.</p>${guidedRatio('vstart','Ensimmäinen väli','m/s','Välin matka','Välin aika')}${guidedRatio('vend','Viimeinen väli','m/s','Välin matka','Välin aika')}<p>Välin keskinopeus sijoitetaan sen keskipisteaikaan.</p>${numericBox('tmid0','Ensimmäisen välin keskipisteaika','s')}${numericBox('tmid1','Viimeisen välin keskipisteaika','s')}<p>${renderEquationPreview('a=(v2-v1)/(t2-t1)')}</p>${guidedRatio('acc','Kiihtyvyyden arvio','m/s²','Keskinopeuksien muutos','Keskipisteaikojen ero')}`}<button id="checkMotion">Tarkista laskut</button></section></div>`;}if(motionStep>=2){body+= `<h2>Päätelmät</h2>${choiceBlock('motionCurve','Mikä kuvaa mittaustuloksia?',motionKind===0?['Kuvaaja on suora ja nopeus pysyi vakiona','Kuvaaja on suora ja nopeus kasvoi','Kuvaaja on käyrä ja nopeus pysyi vakiona','Kuvaaja on käyrä ja nopeus pieneni']:['Liike oli kiihtyvää: kuvaaja jyrkkenee ja nopeus kasvaa','Kuvaaja on suora ja nopeus kasvoi','Kuvaaja on jyrkkenevä käyrä ja nopeus säilyi','Kuvaaja on loiveneva käyrä ja nopeus kasvoi'])}${choiceBlock('motionReason','Miten kuvaajan jyrkkyys liittyy nopeuteen?',['Jyrkempi matka–aika-kuvaaja tarkoittaa suurempaa nopeutta','Korkeampi piste tarkoittaa aina suurempaa nopeutta','Nopeus on vaaka-akselin lukema','Käyrän pituus määrää nopeuden'])}${motionKind===2?`<p>Oma kiihtyvyysarviosi: ${fmt(motionStudentAcceleration??motionEst().a)} m/s². Maan putoamiskiihtyvyys on noin 9,8 m/s².</p>${choiceBlock('motionLimits','Mikä voi selittää arvion poikkeaman?',['Mittauslukemien ja välitulosten pyöristäminen; putoamiskiihtyvyys on mallissa likiarvo','Suurempi kuula olisi kiihtynyt nopeammin ja korjannut arvion'])}`:''}<button id="motionConclusions">Tarkista päätelmät</button>`;}
 el('app').innerHTML=`<button id="motionHome" class="secondary">← Liiketutkimukset</button>${steps(motionStep)}<article class="panel">${body}<div id="feedback" class="feedback" role="status"></div></article>`;el('motionHome').onclick=()=>{motionMenu=true;drawMotion();};if(motionStep===0)el('startMotion').onclick=()=>{motionStep=1;const n=motionKind===0?4:motionKind===1?8:8;marks=Array.from({length:n},(_,i)=>(i+1)*length()/n);drawMotion();};if(motionStep===1){el('runMotion').onclick=()=>{if(motionRun||motionT>=endTime())return;motionRun=true;motionLast=performance.now();el('runMotion').disabled=true;motionRAF=requestAnimationFrame(motionTick);};el('capture').onclick=capture;el('retryMotion').onclick=()=>{motionT=0;captured=[];drawMotion();};el('motionResults').onclick=()=>{if(captured.length<marks.length){message('Kirjaa kaikki väliajat.',false);return;}motionStep=2;drawMotion();};}
 if(motionStep===2)bindRatioPreviews();if(motionStep===2)el('checkMotion').onclick=()=>{const e=motionEst(),fit=motionFit();let specs;if(motionKind===0){const dt=motionTriangleTime();specs=[['speedNumerator',fit.k*dt],['speedDenominator',dt],['speedValue',fit.k]];}else specs=[['vstartNumerator',e.ds0],['vstartDenominator',e.dt0],['vstartValue',e.v0],['vendNumerator',e.ds1],['vendDenominator',e.dt1],['vendValue',e.v1],['tmid0',e.t0],['tmid1',e.t1],['accNumerator',e.v1-e.v0],['accDenominator',e.t1-e.t0],['accValue',e.a]];const valid=([id,v])=>{const ratio=id.endsWith('Value'),target=ratio?number(el(id.replace('Value','Numerator')).value)/number(el(id.replace('Value','Denominator')).value):v;return Number.isFinite(target)&&near(number(el(id).value),target,ratio?.04:.15);};let bad=specs.filter(spec=>!valid(spec));specs.forEach(spec=>{let n=el(spec[0]+'Status');if(n)n.textContent=valid(spec)?'✓':'Tarkista';});if(bad.length){message('Tarkista merkityt kohdat taulukosta ja kuvaajasta.',false);return;}motionStudentAcceleration=motionKind===0?null:number(el('accValue').value);message('✓ Laskut oikein.',true);};if(motionStep>=2)el('motionConclusions').onclick=()=>{let good=pickValue('motionCurve')==='0'&&pickValue('motionReason')==='0'&&(motionKind!==2||pickValue('motionLimits')==='0');message(good?'✓ Liikkeen tulkinta oikein.':'Vertaa nopeuden muutosta kuvaajan jyrkkyyteen.',good);};}
function capture(){if(motionStep!==1||captured.length>=marks.length||motionT===0)return;if(!motionRun&&motionT<endTime())return;const target=marks[captured.length],spacing=length()/marks.length;if(Math.abs(pos()-target)>spacing*.48){message('Kirjaa, kun kappale on lähempänä pyydettyä merkkiä.',false);return;}if(captured.length&&motionT<=captured.at(-1)[0])return;captured.push([motionT,target]);el('motionTable').innerHTML=motionDataTable();el('capture').textContent=captured.length===marks.length?'Kaikki väliajat kirjattu':'Väliaika: '+fmt(marks[captured.length])+' m';if(captured.length===marks.length){el('capture').disabled=true;message('Mittaus valmis.',true);}}
function motionTick(now){if(!motionRun)return;motionT=Math.min(endTime(),motionT+(now-motionLast)/1000/(motionKind===0?1:2));motionLast=now;updateMotionScene();el('motionClock').textContent='t = '+motionT.toFixed(2).replace('.',',')+' s';if(motionT>=endTime()){motionRun=false;message('Kirjaa viimeinen väliaika.',true);}else motionRAF=requestAnimationFrame(motionTick);}
const baseMotionArtwork=illustratedMotion;
illustratedMotion=function(){if(motionKind!==0)return baseMotionArtwork();let s=sceneOpen(400,'Leikkiauto pitkällä koulupöydällä')+inkBench(190)+`<path d="M36 214 V375 M573 214 V375" stroke="url(#steel)" stroke-width="10"/><path d="M30 375 H64 M555 375 H590" stroke="#435953" stroke-width="3"/><path d="M60 201 H530 V224 H60 Z" fill="#fffdf3" stroke="#435953"/>`;for(let i=0;i<=16;i++){let x=60+i*470/16;s+=`<path d="M${x} 203 v${i%4===0?16:8}" stroke="#263d37" stroke-width="1.3"/>${i%4===0?`<text x="${x}" y="249" text-anchor="middle">${i/4}</text>`:''}`;}s+=`<g transform="translate(60 178)"><g id="motionSprite" transform="${motionSpriteTransform()}">${artImage('car',-51,-20.3,103,34.33)}`;for(let i=0;i<2;i++){const x=i?31.5:-23.5;s+=`<g id="motionWheel${i}" transform="translate(${x} 6.2) rotate(${pos()/.025*180/Math.PI})"><path d="M-4.2 0 H4.2 M0 -4.2 V4.2" stroke="#fbf7df" stroke-width=".7"/></g>`;}return s+'</g></g><text x="310" y="395" text-anchor="middle">Matka (m)</text></svg>';};

