function heatCaptureNotes(){const n=heatNotes[heatKind]||(heatNotes[heatKind]={});if(heatStep===0&&el('heatHypothesis'))readPlan('heat',n.plan||(n.plan={}));if(heatStep===2){n.observation=pickValue('heatObservation');n.explanation=pickValue('heatExplanation');n.reliability=pickValue('heatReliability');}persistHeat();}
function captureExpNotes(){const s=expState();if(s.step===0&&el('expHypothesis'))readPlan('exp',s.plan||(s.plan={}));if(s.step===2)expAnswerSpecs().forEach((_,i)=>{if(el('expAnswer'+i))s.answers[i]=el('expAnswer'+i).value;});if(s.step>=2)s.notes.conclusions={observation:pickValue('expObservation'),explanation:pickValue('expExplanation'),reliability:pickValue('expReliability')};persistExp();}

function planningArtwork(prefix,c){const key=prefix==='expansion'?'expansion':prefix==='heat'?['liquids','surfaces','cooling'][heatKind]:({load:'friction-load',material:'friction-material',buoyancy:'buoyancy'})[studyKey]||'power';return `<img class="planning-art" src="assets/planning-${key}-v1.png" alt="${esc(c.title||c.question)}: koeasetelma luokkahuoneessa">`;}
function workspaceSource(raw){let s=raw.trim().replace(/^\$|\$$/g,'').replace(/\\(?:cdot|times)/g,'*').replace(/\\Delta/g,'Δ').replace(/\\rho/g,'ρ').replace(/\\(?:left|right)/g,'');function group(at){if(s[at]!=='{')return null;let depth=1,end=at+1;while(end<s.length&&depth){if(s[end]==='{')depth++;if(s[end]==='}')depth--;end++;}return depth?null:{text:s.slice(at+1,end-1),end};}for(let count=0;count<40;count++){let at=s.lastIndexOf('\\frac');if(at<0)break;let a=group(at+5);if(!a)break;let b=group(a.end);if(!b)break;s=s.slice(0,at)+'('+a.text+')/('+b.text+')'+s.slice(b.end);}s=s.replace(/\\sqrt\{([^{}]+)\}/g,'sqrt($1)').replace(/\\(?:mathrm|text)\{([^{}]+)\}/g,'$1').replace(/\^\{([^{}]+)\}/g,'^($1)');return s;}
function renderWorkspaceLines(raw){return raw.split('\n').map(line=>{if(!line.trim())return '<div class="workspace-spacer"></div>';if(/\\|\$/.test(line)&&typeof katex!=='undefined')return workspaceTex(line);const s=workspaceSource(line),operators=s.match(/[=≈]/g)||[],parts=s.split(/[=≈]/);let rendered;try{if(!/[=≈+*/^]|sqrt\(/.test(s))return `<p class="workspace-note">${esc(line)}</p>`;rendered=Mwrap(Mtag('mrow',...parts.flatMap((part,i)=>{let m;try{m=qparse(part).m;}catch{m=symparse(part).m;}return [...(i?[Mtag('mo',operators[i-1])]:[]),m];})));}catch{if(typeof katex!=='undefined'&&/^[A-Za-zρΔαη0-9(]/.test(s)&&!/[<>]/.test(s))return workspaceTex(line);return `<p class="workspace-note">${esc(line)}</p>`;}return `<div class="workspace-equation">${rendered}</div>`;}).join('');}

function workspaceMath(source,display=false){if(typeof katex==='undefined')return esc(source);try{return katex.renderToString(source,{displayMode:display,throwOnError:true,trust:false,strict:'ignore',maxExpand:1000,output:'htmlAndMathml'});}catch{return esc(source);}}
function workspaceTex(line){if(line.includes('$')){let at=0,out='',matches=[...line.matchAll(/\$([^$]+)\$/g)];for(const m of matches){out+=esc(line.slice(at,m.index))+workspaceMath(m[1]);at=m.index+m[0].length;}if(matches.length)return `<p class="workspace-note">${out+esc(line.slice(at))}</p>`;}return `<div class="workspace-equation">${workspaceMath(line)}</div>`;}
function renderWorkspace(raw){const pattern=/\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\begin\{aligned\}[\s\S]*?\\end\{aligned\}/g;let at=0,out='',m;while((m=pattern.exec(raw))){out+=renderWorkspaceLines(raw.slice(at,m.index));const content=m[0].startsWith('$$')?m[0].slice(2,-2):m[0].startsWith('\\[')?m[0].slice(2,-2):m[0];out+=`<div class="workspace-equation">${workspaceMath(content,true)}</div>`;at=m.index+m[0].length;}return out+renderWorkspaceLines(raw.slice(at));}
